export const KimiK26Deployment = () => {
  // Config mirrors sgl-cookbook src/components/autoregressive/KimiK26ConfigGenerator/index.js.
  //
  // INT4:
  //   H200/B300: tp=8
  //   GB300/AMD: tp=4
  //
  // NVFP4:
  //   B300: tp=8
  //   GB300: tp=4
  //
  // Ascend A3: W4A8 INT8 (ModelSlim) only; 1×A3 PD co-located or 2×A3 PD
  //   disaggregated, generated by generateAscendA3Command (port 30000 per
  //   cookbook convention; router stays on 6688).
  const options = {
    hardware: {
      name: 'hardware',
      title: 'Hardware Platform',
      items: [
        { id: 'h200', label: 'H200', default: true },
        { id: 'b300', label: 'B300', default: false },
        { id: 'gb300', label: 'GB300', default: false },
        { id: 'mi300x', label: 'MI300X', default: false },
        { id: 'mi325x', label: 'MI325X', default: false },
        { id: 'mi350x', label: 'MI350X', default: false },
        { id: 'mi355x', label: 'MI355X', default: false },
        { id: 'ascend-a3', label: 'A3', default: false },
      ],
    },
    quantization: {
      name: 'quantization',
      title: 'Quantization',
      getDynamicItems: (values) => {
        const hw = values.hardware;
        if (hw === 'ascend-a3') {
          return [
            { id: 'w4a8', label: 'W4A8', subtitle: 'INT8 (ModelSlim)', default: true },
          ];
        }
        const isBlackwell = ['b300', 'gb300'].includes(hw);
        return [
          { id: 'int4', label: 'INT4', subtitle: 'Base checkpoint', default: !isBlackwell },
          { id: 'nvfp4', label: 'NVFP4', subtitle: 'Blackwell FP4', default: isBlackwell, disabled: !isBlackwell, disabledReason: !isBlackwell ? 'NVFP4 only on NVIDIA Blackwell' : '' },
        ];
      },
    },
    reasoning: {
      name: 'reasoning',
      title: 'Reasoning Parser',
      items: [
        { id: 'disabled', label: 'Disabled', default: false },
        { id: 'enabled', label: 'Enabled', default: true },
      ],
    },
    toolcall: {
      name: 'toolcall',
      title: 'Tool Call Parser',
      items: [
        { id: 'disabled', label: 'Disabled', default: false },
        { id: 'enabled', label: 'Enabled', default: true },
      ],
    },
    dpattention: {
      name: 'dpattention',
      title: 'DP Attention',
      condition: (values) => values.hardware !== 'ascend-a3',
      items: [
        { id: 'disabled', label: 'Disabled', subtitle: 'Low Latency', default: true },
        { id: 'enabled', label: 'Enabled', subtitle: 'High Throughput', default: false },
      ],
    },
    speculative: {
      name: 'speculative',
      title: 'Speculative Decoding',
      condition: (values) => !['mi300x', 'mi325x', 'mi350x', 'mi355x'].includes(values.hardware),
      items: [
        { id: 'disabled', label: 'Disabled', default: true },
        { id: 'enabled', label: 'Enabled', default: false },
      ],
    },
    deployshape: {
      name: 'deployshape',
      title: 'Deployment Shape',
      condition: (values) => values.hardware === 'ascend-a3',
      items: [
        { id: 'colocated', label: '1×A3 · PD Co-located', subtitle: 'Low Latency', default: true },
        { id: 'pd2node', label: '2×A3 · PD Disaggregated', subtitle: 'High Throughput', default: false },
      ],
    },
  };

  const modelConfigs = {
    h200: { tp: 8 },
    b300: { tp: 8 },
    gb300: { tp: 4 },
    mi300x: { tp: 4 },
    mi325x: { tp: 4 },
    mi350x: { tp: 4 },
    mi355x: { tp: 4 },
  };

  const nvfp4ModelConfigs = {
    b300: { tp: 8 },
    gb300: { tp: 4 },
  };

  const resolveItems = (option, values) =>
    typeof option.getDynamicItems === 'function' ? option.getDynamicItems(values) : option.items || [];

  const getInitialState = () => {
    const initialState = {};
    for (const [key, option] of Object.entries(options)) {
      const items = resolveItems(option, initialState);
      const def = items.find((item) => item.default && !item.disabled) || items.find((item) => !item.disabled) || items[0];
      initialState[key] = def.id;
    }
    return initialState;
  };

  const [values, setValues] = useState(getInitialState);
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    const checkDarkMode = () => {
      const html = document.documentElement;
      const isDarkMode =
        html.classList.contains('dark') ||
        html.getAttribute('data-theme') === 'dark' ||
        html.style.colorScheme === 'dark';
      setIsDark(isDarkMode);
    };

    checkDarkMode();
    const observer = new MutationObserver(checkDarkMode);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['class', 'data-theme', 'style'],
    });
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    setValues((prev) => {
      const next = { ...prev };
      for (const [key, option] of Object.entries(options)) {
        if (typeof option.condition === 'function' && !option.condition(next)) {
          const items = resolveItems(option, next);
          const fallback = items.find((item) => item.default && !item.disabled) || items.find((item) => !item.disabled);
          if (fallback) next[key] = fallback.id;
          continue;
        }
        if (typeof option.getDynamicItems !== 'function') continue;
        const items = option.getDynamicItems(next);
        const current = items.find((item) => item.id === next[key]);
        if (!current || current.disabled) {
          const fallback = items.find((item) => item.default && !item.disabled) || items.find((item) => !item.disabled);
          if (fallback) next[key] = fallback.id;
        }
      }
      return next;
    });
  }, [values.hardware]);

  const handleRadioChange = (optionName, value) => {
    setValues((prev) => {
      const next = { ...prev, [optionName]: value };
      // The A3 recipes and the §3.3 benchmarks run with an EAGLE3 draft;
      // default speculative decoding to enabled when A3 is selected (still user-toggleable).
      if (optionName === 'hardware' && value === 'ascend-a3') next.speculative = 'enabled';
      return next;
    });
  };

  // Ascend A3 recipes mirror docs/cookbook/autoregressive/Moonshotai/Kimi-K2.6.mdx §3.3
  // (W4A8 INT8 checkpoint + EAGLE3 draft; servers listen on port 30000 per cookbook convention).
  const generateAscendA3Command = () => {
    const { deployshape, speculative, reasoning, toolcall } = values;
    const spec = speculative === 'enabled';

    const parserFlags =
      (reasoning === 'enabled' ? ' \\\n    --reasoning-parser kimi_k2' : '') +
      (toolcall === 'enabled' ? ' \\\n    --tool-call-parser kimi_k2' : '');

    const draftLine = spec ? 'DRAFT_MODEL_PATH=/path/to/kimi-k2.6-eagle3\n' : '';
    const specFlags = spec
      ? ' \\\n    --speculative-algorithm EAGLE3' +
        ' \\\n    --speculative-draft-model-path $DRAFT_MODEL_PATH' +
        ' \\\n    --speculative-num-steps 4' +
        ' \\\n    --speculative-eagle-topk 1' +
        ' \\\n    --speculative-num-draft-tokens 5' +
        ' \\\n    --speculative-draft-model-quantization unquant'
      : '';

    const header =
      '# ============================================================\n' +
      '# Before running, update the following variables:\n' +
      '#   MODEL_PATH: path to the W4A8 model weights directory\n' +
      (spec ? '#   DRAFT_MODEL_PATH: path to the EAGLE3 draft model weights directory\n' : '') +
      '#   HCCL_SOCKET_IFNAME / GLOO_SOCKET_IFNAME: host network interface (e.g. eth0)\n' +
      '# ============================================================\n\n' +
      'MODEL_PATH=/path/to/Kimi-K2.6-w4a8\n' +
      draftLine +
      '\n' +
      'echo performance | tee /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor\n' +
      'sysctl -w vm.swappiness=0\n' +
      'sysctl -w kernel.numa_balancing=0\n' +
      'sysctl -w kernel.sched_migration_cost_ns=50000\n\n' +
      'unset https_proxy\nunset http_proxy\nunset HTTPS_PROXY\nunset HTTP_PROXY\nunset ASCEND_LAUNCH_BLOCKING\n\n' +
      'source /usr/local/Ascend/ascend-toolkit/set_env.sh\n' +
      'source /usr/local/Ascend/nnal/atb/set_env.sh\n\n';

    if (deployshape === 'colocated') {
      return (
        header +
        'export DEEPEP_HCCL_BUFFSIZE=1200\n' +
        'export DEEP_NORMAL_MODE_USE_INT8_QUANT=1\n' +
        'export GLOO_SOCKET_IFNAME=<network-interface>\n' +
        'export HCCL_OP_EXPANSION_MODE=AIV\n' +
        'export HCCL_SOCKET_IFNAME=<network-interface>\n' +
        'export PYTORCH_NPU_ALLOC_CONF=expandable_segments:True\n' +
        'export SGLANG_DEEPEP_NUM_MAX_DISPATCH_TOKENS_PER_RANK=96\n' +
        'export SGLANG_DISAGGREGATION_BOOTSTRAP_TIMEOUT=600\n' +
        'export SGLANG_ENABLE_OVERLAP_PLAN_STREAM=1\n' +
        'export SGLANG_NPU_USE_MLAPO=1\n' +
        'export SGLANG_NPU_USE_MULTI_STREAM=1\n' +
        'export SGLANG_SET_CPU_AFFINITY=1\n' +
        'export STREAMS_PER_DEVICE=32\n\n' +
        'sglang serve \\\n' +
        '    --model-path $MODEL_PATH \\\n' +
        '    --host 0.0.0.0 --port 30000 \\\n' +
        '    --trust-remote-code \\\n' +
        '    --attention-backend ascend \\\n' +
        '    --device npu \\\n' +
        '    --quantization modelslim \\\n' +
        '    --dtype bfloat16 \\\n' +
        '    --tp-size 16 \\\n' +
        '    --mem-fraction-static 0.865 \\\n' +
        '    --max-running-requests 80 \\\n' +
        '    --chunked-prefill-size 32768 \\\n' +
        '    --context-length 6144 \\\n' +
        '    --max-prefill-tokens 65536 \\\n' +
        '    --enable-multimodal \\\n' +
        '    --mm-attention-backend ascend_attn \\\n' +
        '    --sampling-backend ascend \\\n' +
        '    --attn-dp-size 16 \\\n' +
        '    --moe-a2a-backend deepep \\\n' +
        '    --deepep-mode auto \\\n' +
        '    --cuda-graph-bs-decode 1 2 3 4 5 \\\n' +
        '    --disable-radix-cache \\\n' +
        "    --model-loader-extra-config '{\"enable_multithread_load\": true}'" +
        specFlags +
        ' \\\n    --prefill-delayer-max-delay-passes 200 \\\n' +
        '    --enable-prefill-delayer' +
        parserFlags
      );
    }

    // 2×A3 PD disaggregated
    const shared =
      header +
      'export DEEP_NORMAL_MODE_USE_INT8_QUANT=1\n' +
      'export PYTORCH_NPU_ALLOC_CONF=expandable_segments:True\n' +
      'export SGLANG_DISAGGREGATION_BOOTSTRAP_TIMEOUT=60\n' +
      'export SGLANG_SET_CPU_AFFINITY=1\n' +
      'export STREAMS_PER_DEVICE=32\n' +
      'export ASCEND_MF_STORE_URL="tcp://<your prefill ip>:24670"\n';

    const prefill =
      '\n# ---- 1. Prefill node (<your prefill ip>) ----\n' +
      'export DEEPEP_HCCL_BUFFSIZE=1800\n' +
      'export GLOO_SOCKET_IFNAME=<network-interface>\n' +
      'export HCCL_SOCKET_IFNAME=<network-interface>\n\n' +
      'sglang serve \\\n' +
      '    --model-path $MODEL_PATH \\\n' +
      '    --disaggregation-mode prefill \\\n' +
      '    --host <your prefill ip> --port 30000 \\\n' +
      '    --disaggregation-bootstrap-port 8998 \\\n' +
      '    --node-rank 0 \\\n' +
      '    --quantization modelslim \\\n' +
      '    --dtype bfloat16 \\\n' +
      '    --disaggregation-transfer-backend ascend \\\n' +
      '    --nnodes 1 \\\n' +
      '    --trust-remote-code \\\n' +
      '    --attention-backend ascend \\\n' +
      '    --device npu \\\n' +
      '    --tp-size 16 \\\n' +
      '    --disable-radix-cache \\\n' +
      '    --disable-cuda-graph \\\n' +
      '    --mem-fraction-static 0.78 \\\n' +
      '    --max-running-requests 1 \\\n' +
      '    --moe-a2a-backend deepep \\\n' +
      '    --deepep-mode auto \\\n' +
      '    --chunked-prefill-size 16384 \\\n' +
      '    --prefill-max-requests 1 \\\n' +
      '    --max-prefill-tokens 65536 \\\n' +
      '    --enable-multimodal \\\n' +
      '    --mm-attention-backend ascend_attn \\\n' +
      '    --sampling-backend ascend' +
      parserFlags +
      '\n';

    const decode =
      '\n# ---- 2. Decode node (<your decode ip>) ----\n' +
      'export DEEPEP_HCCL_BUFFSIZE=1200\n' +
      'export GLOO_SOCKET_IFNAME=<network-interface>\n' +
      'export HCCL_SOCKET_IFNAME=<network-interface>\n' +
      'export SGLANG_DEEPEP_NUM_MAX_DISPATCH_TOKENS_PER_RANK=64\n' +
      'export SGLANG_ENABLE_OVERLAP_PLAN_STREAM=1\n' +
      'export SGLANG_NPU_USE_MLAPO=1\n' +
      'export SGLANG_NPU_USE_MULTI_STREAM=1\n\n' +
      'sglang serve \\\n' +
      '    --model-path $MODEL_PATH \\\n' +
      '    --disaggregation-mode decode \\\n' +
      '    --host <your decode ip> --port 30000 \\\n' +
      '    --quantization modelslim \\\n' +
      '    --dtype bfloat16 \\\n' +
      '    --disaggregation-transfer-backend ascend \\\n' +
      '    --nnodes 1 \\\n' +
      '    --trust-remote-code \\\n' +
      '    --attention-backend ascend \\\n' +
      '    --device npu \\\n' +
      '    --tp-size 16 \\\n' +
      '    --mem-fraction-static 0.82 \\\n' +
      '    --max-running-requests 16 \\\n' +
      '    --enable-dp-lm-head \\\n' +
      '    --disable-radix-cache \\\n' +
      '    --enable-multimodal \\\n' +
      '    --mm-attention-backend ascend_attn \\\n' +
      '    --sampling-backend ascend \\\n' +
      '    --moe-a2a-backend deepep \\\n' +
      '    --deepep-mode auto \\\n' +
      '    --cuda-graph-bs-decode 16' +
      parserFlags +
      specFlags +
      '\n';

    const router =
      '\n# ---- 3. Router (either node, or a separate CPU host) ----\n' +
      'python -m sglang_router.launch_router \\\n' +
      '    --pd-disaggregation \\\n' +
      '    --prefill http://<your prefill ip>:30000 8998 \\\n' +
      '    --decode http://<your decode ip>:30000 \\\n' +
      '    --host 127.0.0.1 \\\n' +
      '    --port 6688 \\\n' +
      '    --policy cache_aware';

    return shared + prefill + decode + router;
  };

  const generateCommand = () => {
    const { hardware, quantization, reasoning, toolcall, dpattention, speculative } = values;
    if (hardware === 'ascend-a3') return generateAscendA3Command();
    const isAMD = hardware === 'mi300x' || hardware === 'mi325x' || hardware === 'mi350x' || hardware === 'mi355x';
    const isNVFP4 = quantization === 'nvfp4';
    const hwConfig = isNVFP4 ? nvfp4ModelConfigs[hardware] : modelConfigs[hardware];
    if (!hwConfig) return '# NVFP4 is only supported on NVIDIA Blackwell hardware.';
    if (speculative === 'enabled' && isAMD) {
      return '# Speculative Decoding for Kimi-K2.6 is only supported on NVIDIA GPUs (H200/B300/GB300)';
    }
    const tpValue = hwConfig.tp;
    const modelName = isNVFP4 ? 'nvidia/Kimi-K2.6-NVFP4' : 'moonshotai/Kimi-K2.6';

    let cmd = '';

    if (isAMD) {
      cmd += 'SGLANG_USE_AITER=1 SGLANG_ROCM_FUSED_DECODE_MLA=0 \\\n';
    }

    cmd += 'sglang serve \\\n';
    cmd += `  --model-path ${modelName}`;
    cmd += ` \\\n  --tp ${tpValue}`;
    if (isNVFP4) {
      cmd += ' \\\n  --quantization modelopt_fp4';
    }
    if (isAMD) {
      cmd += ' \\\n  --mem-fraction-static 0.8';
    }
    cmd += ' \\\n  --trust-remote-code';

    if (dpattention === 'enabled') {
      cmd += ` \\\n  --attn-dp-size ${tpValue}`;
    }

    if (reasoning === 'enabled') {
      cmd += ' \\\n  --reasoning-parser kimi_k2';
    }

    if (toolcall === 'enabled') {
      cmd += ' \\\n  --tool-call-parser kimi_k2';
    }

    if (speculative === 'enabled') {
      cmd += ' \\\n  --speculative-algorithm EAGLE3';
      cmd += ' \\\n  --speculative-num-steps 3';
      cmd += ' \\\n  --speculative-eagle-topk 1';
      cmd += ' \\\n  --speculative-num-draft-tokens 4';
      cmd += ' \\\n  --speculative-draft-model-path lightseekorg/kimi-k2.6-eagle3.1-mla';
    }

    const usesCutedslMla = hardware === 'b300' || hardware === 'gb300';

    if (usesCutedslMla) {
      cmd += ' \\\n  --attention-backend cutedsl_mla';
      if (speculative === 'enabled') {
        cmd += ' \\\n  --speculative-attention-mode decode';
      }
    }

    if (isAMD || usesCutedslMla) {
      cmd += ' \\\n  --kv-cache-dtype fp8_e4m3';
    }

    cmd += ' \\\n  --host 0.0.0.0 \\\n  --port 30000';
    return cmd;
  };

  const containerStyle = { maxWidth: '900px', margin: '0 auto', display: 'flex', flexDirection: 'column', gap: '4px' };
  const cardStyle = { padding: '8px 12px', border: `1px solid ${isDark ? '#374151' : '#e5e7eb'}`, borderLeft: `3px solid ${isDark ? '#E85D4D' : '#D45D44'}`, borderRadius: '4px', display: 'flex', alignItems: 'center', gap: '12px', background: isDark ? '#1f2937' : '#fff' };
  const titleStyle = { fontSize: '13px', fontWeight: '600', minWidth: '140px', flexShrink: 0, color: isDark ? '#e5e7eb' : 'inherit' };
  const itemsStyle = { display: 'flex', rowGap: '2px', columnGap: '6px', flexWrap: 'wrap', alignItems: 'center', flex: 1 };
  const labelBaseStyle = { padding: '4px 10px', border: `1px solid ${isDark ? '#9ca3af' : '#d1d5db'}`, borderRadius: '3px', cursor: 'pointer', display: 'inline-flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', fontWeight: '500', fontSize: '13px', transition: 'all 0.2s', userSelect: 'none', minWidth: '45px', textAlign: 'center', flex: 1, background: isDark ? '#374151' : '#fff', color: isDark ? '#e5e7eb' : 'inherit' };
  const checkedStyle = { background: '#D45D44', color: 'white', borderColor: '#D45D44' };
  const disabledStyle = { cursor: 'not-allowed', opacity: 0.4 };
  const subtitleStyle = { display: 'block', fontSize: '9px', marginTop: '1px', lineHeight: '1.1', opacity: 0.7 };
  const commandDisplayStyle = { flex: 1, padding: '12px 16px', background: isDark ? '#111827' : '#f5f5f5', borderRadius: '6px', fontFamily: "'Menlo', 'Monaco', 'Courier New', monospace", fontSize: '12px', lineHeight: '1.5', color: isDark ? '#e5e7eb' : '#374151', whiteSpace: 'pre-wrap', overflowX: 'auto', margin: 0, border: `1px solid ${isDark ? '#374151' : '#e5e7eb'}` };

  return (
    <div style={containerStyle} className="not-prose">
      {Object.entries(options).map(([key, option]) => {
        if (typeof option.condition === 'function' && !option.condition(values)) return null;
        const items = resolveItems(option, values);
        return (
          <div key={key} style={cardStyle}>
            <div style={titleStyle}>{option.title}</div>
            <div style={itemsStyle}>
              {items.map((item) => {
                const isChecked = values[option.name] === item.id;
                const isDisabled = !!item.disabled;
                return (
                  <label
                    key={item.id}
                    style={{ ...labelBaseStyle, ...(isChecked ? checkedStyle : {}), ...(isDisabled ? disabledStyle : {}) }}
                    title={item.disabledReason || ''}
                  >
                    <input
                      type="radio"
                      name={option.name}
                      value={item.id}
                      checked={isChecked}
                      disabled={isDisabled}
                      onChange={() => !isDisabled && handleRadioChange(option.name, item.id)}
                      style={{ display: 'none' }}
                    />
                    {item.label}
                    {item.subtitle && <small style={{ ...subtitleStyle, color: isChecked ? 'rgba(255,255,255,0.85)' : 'inherit' }}>{item.subtitle}</small>}
                  </label>
                );
              })}
            </div>
          </div>
        );
      })}
      <div style={cardStyle}>
        <div style={titleStyle}>Run this Command:</div>
        <pre style={commandDisplayStyle}>{generateCommand()}</pre>
      </div>
    </div>
  );
};
